#!/usr/bin/env bash
set -euo pipefail

# VanoLeaf -> native macOS application installer
# Drop THIS ONE FILE inside your existing VanoLeaf folder and run it.

PROJECT_DIR="$(cd "$(dirname "$0")" && pwd)"
cd "$PROJECT_DIR"

if [[ "$(uname -s)" != "Darwin" ]]; then
  echo "This installer is for macOS only."
  exit 1
fi

for required in app.py index.html; do
  if [[ ! -f "$required" ]]; then
    echo "Missing $required in: $PROJECT_DIR"
    echo "Put this installer directly inside your VanoLeaf folder."
    exit 1
  fi
done

if [[ ! -d vendor ]]; then
  echo "Missing vendor/ folder in: $PROJECT_DIR"
  exit 1
fi

PYTHON=""
for candidate in /opt/homebrew/bin/python3 /usr/local/bin/python3 "$(command -v python3 2>/dev/null || true)"; do
  if [[ -n "$candidate" && -x "$candidate" ]]; then
    PYTHON="$candidate"
    break
  fi
done

if [[ -z "$PYTHON" ]]; then
  echo "Python 3 was not found."
  echo "Install it first with: brew install python3"
  exit 1
fi

echo "== VanoLeaf macOS App Installer =="
echo "Project: $PROJECT_DIR"
echo "Python:  $PYTHON"

VENV="$PROJECT_DIR/.venv-mac-app"
if [[ ! -d "$VENV" ]]; then
  echo "Creating dedicated build environment..."
  "$PYTHON" -m venv "$VENV"
fi

source "$VENV/bin/activate"
python -m pip install --quiet --upgrade pip setuptools wheel

echo "Installing native-window/build dependencies..."
python -m pip install --quiet \
  'Flask>=3.0,<4.0' \
  'pywebview>=5.3,<7.0' \
  'py2app>=0.28' \
  'pyobjc-core>=10.0' \
  'pyobjc-framework-Cocoa>=10.0' \
  'pyobjc-framework-Quartz>=10.0' \
  'pyobjc-framework-WebKit>=10.0' \
  'pyobjc-framework-Security>=10.0'

BUILD_ROOT="$PROJECT_DIR/.vanoleaf_mac_build"
rm -rf "$BUILD_ROOT"
mkdir -p "$BUILD_ROOT/assets"

# The project location is embedded at install time, so the .app always opens
# the exact VanoLeaf folder you already use (projects, index.html, vendor, etc.).
PROJECT_DIR_JSON=$(python - <<'PY' "$PROJECT_DIR"
import json, sys
print(json.dumps(sys.argv[1]))
PY
)

cat > "$BUILD_ROOT/mac_app.py" <<PY
#!/usr/bin/env python3
from __future__ import annotations

import os
import sys
import threading
from pathlib import Path

PROJECT_DIR = Path($PROJECT_DIR_JSON).resolve()


def enrich_path():
    home = Path.home()
    candidates = [
        str(home / ".local" / "bin"),
        "/Library/TeX/texbin",
        "/opt/homebrew/bin",
        "/opt/homebrew/sbin",
        "/usr/local/bin",
        "/usr/local/sbin",
        str(home / "Library" / "TinyTeX" / "bin" / "universal-darwin"),
    ]
    current = os.environ.get("PATH", "")
    paths = [p for p in candidates if Path(p).exists()]
    paths += [p for p in current.split(os.pathsep) if p]
    os.environ["PATH"] = os.pathsep.join(dict.fromkeys(paths))


def main():
    if not PROJECT_DIR.exists():
        raise RuntimeError(f"VanoLeaf project folder not found: {PROJECT_DIR}")

    os.chdir(PROJECT_DIR)
    sys.path.insert(0, str(PROJECT_DIR))
    enrich_path()

    from werkzeug.serving import make_server
    import webview
    import app as vanoleaf

    # Use an available local port; no Chrome/Safari window is opened.
    server = make_server("127.0.0.1", 0, vanoleaf.app, threaded=True)
    port = server.server_port
    thread = threading.Thread(target=server.serve_forever, daemon=True)
    thread.start()

    storage = Path.home() / "Library" / "Application Support" / "VanoLeaf" / "WebView"
    storage.mkdir(parents=True, exist_ok=True)

    window = webview.create_window(
        "VanoLeaf",
        f"http://127.0.0.1:{port}",
        width=1480,
        height=940,
        min_size=(1000, 650),
        resizable=True,
        fullscreen=False,
        background_color="#eef4f6",
        text_select=True,
        zoomable=True,
    )

    def after_load():
        try:
            window.evaluate_js("""
                (() => {
                  const b = document.getElementById('newWindowBtn');
                  if (b) b.style.display = 'none';
                  document.documentElement.classList.add('vanoleaf-native-app');
                })();
            """)
        except Exception:
            pass

    window.events.loaded += after_load

    try:
        webview.start(private_mode=False, storage_path=str(storage), debug=False)
    finally:
        server.shutdown()
        server.server_close()
        thread.join(timeout=2)


if __name__ == "__main__":
    main()
PY

cat > "$BUILD_ROOT/setup.py" <<'PY'
from setuptools import setup
from pathlib import Path

ROOT = Path(__file__).resolve().parent
ICON = ROOT / "assets" / "VanoLeaf.icns"

OPTIONS = {
    "argv_emulation": False,
    "strip": True,
    "packages": ["flask", "webview"],
    "includes": [
        "WebKit", "Foundation", "AppKit", "Quartz", "Security",
        "werkzeug", "jinja2", "click",
    ],
    "iconfile": str(ICON) if ICON.exists() else None,
    "plist": {
        "CFBundleName": "VanoLeaf",
        "CFBundleDisplayName": "VanoLeaf",
        "CFBundleIdentifier": "com.vanoleaf.editor",
        "CFBundleShortVersionString": "1.0.0",
        "CFBundleVersion": "1",
        "NSHighResolutionCapable": True,
        "NSPrincipalClass": "NSApplication",
        "NSAppTransportSecurity": {"NSAllowsLocalNetworking": True},
        "LSMinimumSystemVersion": "12.0",
    },
}

setup(
    name="VanoLeaf",
    version="1.0.0",
    app=["mac_app.py"],
    options={"py2app": OPTIONS},
    setup_requires=["py2app"],
)
PY

# Built-in VanoLeaf leaf icon. No extra icon file is required from the user.
ICON_B64=''
printf '%s' "$ICON_B64" | base64 --decode > "$BUILD_ROOT/assets/VanoLeaf-1024.png"

ICONSET="$BUILD_ROOT/assets/VanoLeaf.iconset"
mkdir -p "$ICONSET"
sips -z 16 16     "$BUILD_ROOT/assets/VanoLeaf-1024.png" --out "$ICONSET/icon_16x16.png" >/dev/null
sips -z 32 32     "$BUILD_ROOT/assets/VanoLeaf-1024.png" --out "$ICONSET/icon_16x16@2x.png" >/dev/null
sips -z 32 32     "$BUILD_ROOT/assets/VanoLeaf-1024.png" --out "$ICONSET/icon_32x32.png" >/dev/null
sips -z 64 64     "$BUILD_ROOT/assets/VanoLeaf-1024.png" --out "$ICONSET/icon_32x32@2x.png" >/dev/null
sips -z 128 128   "$BUILD_ROOT/assets/VanoLeaf-1024.png" --out "$ICONSET/icon_128x128.png" >/dev/null
sips -z 256 256   "$BUILD_ROOT/assets/VanoLeaf-1024.png" --out "$ICONSET/icon_128x128@2x.png" >/dev/null
sips -z 256 256   "$BUILD_ROOT/assets/VanoLeaf-1024.png" --out "$ICONSET/icon_256x256.png" >/dev/null
sips -z 512 512   "$BUILD_ROOT/assets/VanoLeaf-1024.png" --out "$ICONSET/icon_256x256@2x.png" >/dev/null
sips -z 512 512   "$BUILD_ROOT/assets/VanoLeaf-1024.png" --out "$ICONSET/icon_512x512.png" >/dev/null
cp "$BUILD_ROOT/assets/VanoLeaf-1024.png" "$ICONSET/icon_512x512@2x.png"
iconutil -c icns "$ICONSET" -o "$BUILD_ROOT/assets/VanoLeaf.icns"
rm -rf "$ICONSET"

echo "Building VanoLeaf.app..."
cd "$BUILD_ROOT"
rm -rf build dist
python setup.py py2app > /tmp/vanoleaf-mac-build.log 2>&1 || {
  echo "Build failed. Last lines of the log:"
  tail -n 100 /tmp/vanoleaf-mac-build.log
  exit 1
}

if [[ ! -d "$BUILD_ROOT/dist/VanoLeaf.app" ]]; then
  echo "Build finished but VanoLeaf.app was not created."
  exit 1
fi

TARGET="/Applications/VanoLeaf.app"
echo "Installing: $TARGET"
if [[ -w /Applications ]]; then
  rm -rf "$TARGET"
  ditto "$BUILD_ROOT/dist/VanoLeaf.app" "$TARGET"
else
  sudo rm -rf "$TARGET"
  sudo ditto "$BUILD_ROOT/dist/VanoLeaf.app" "$TARGET"
fi

codesign --force --deep --sign - "$TARGET" >/dev/null 2>&1 || true
xattr -dr com.apple.quarantine "$TARGET" 2>/dev/null || true

echo ""
echo "Done. VanoLeaf is now a Mac application:"
echo "  /Applications/VanoLeaf.app"
echo ""
echo "It uses your existing project folder:"
echo "  $PROJECT_DIR"
echo ""
echo "Opening VanoLeaf..."
open "$TARGET"
